INSERT INTO "main"."CollectionData" ("Id", "Data", "CreatedOn", "UpdatedOn") VALUES ('WhoWeArePage', '{"Intro":{"Logo":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Title":"We are students and teachers, engineers and pharmacists, poets and painters and truck drivers and singers.","Description":"<p>We are medical doctors and university lecturers. We are designers and psychologists and physical therapists.We are Lebanese and Yemini and Syrian and Palestinian. We are Iraqi and Jordanian. We are Arab speaking or we are not. We were born in America or we just got here last month. We are Arab and we are American. We are a diverse group of people of all ages, sexual preferences, and political and religious backgrounds. We are Al Nadwa FTS.</p>"},"Founders":[{"FullName":"Mr. Aoun Jaber","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"President and a founding member of Alnadwa Freethinking Society."},{"FullName":"Adnan Jaber Ph.D","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Vice President"},{"FullName":"Souad Maadarani MA","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Treasurer"},{"FullName":"Abbas Youssef Ph.D., MBA","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Secretary"},{"FullName":"Ziyad Nasr","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Member at Large of the Executive Board"}],"BoardMembers":[{"FullName":"Wissam Charafeddine","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Board Member"},{"FullName":"Rewa Zeinati","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Board Member"},{"FullName":"Hassan Chami","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Board Member"},{"FullName":"Radwan Dabaja","Info":"Board Member","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad"},{"FullName":"Hanan Charara","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Board Member"},{"FullName":"Khalil Elsaghir","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","Info":"Board Member"},{"Info":"Board Member","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","FullName":"Khadija Hussein D. D. S"},{"Info":"Director at large","Image":"a8d63ef7-9db3-4ccc-9bf0-f6835363b6ad","FullName":"Mohamad Sakr"}],"Visions":[{"Icon":"EmojiObjects","Header":"Free Thinking","Info":"<h1>Free Thinking</h1><p> To build and uphold a more freethinking mindset among our Arab-American communities.</p>","Feature":true},{"Icon":"Diversity1","Header":"Diversity and Inclusion","Info":"<h1>Diversity and Inclusion</h1> <p>Embracing diversity and ensuring inclusively in our community.</p>"},{"Header":"Promoting Creativity","Info":"<h1>Promoting Creativity</h1> <p>We celebrate and promote creativity in all its forms.</p>","Icon":"AdsClick"},{"Icon":"Science","Header":"Scientific Reasoning","Info":"<h1>Scientific Reasoning</h1> <p>Encouraging scientific reasoning and critical thinking among individuals.</p>"}]}', '1718032997531', '1718116369921');